import {
  HAL_WS_SUBPROTOCOL,
  credentialFromSubprotocol,
  type IncomingMessage,
  type ListSessionsMessage,
  type OutgoingMessage,
  type SessionListMessage,
  type SessionSummaryFrame,
} from './index.js';
import * as subprotocol from './transport/ws/subprotocol.js';

describe('the package root', () => {
  it('exports the hal.v1 marker with the reader a WsAuthenticator uses', () => {
    expect({marker: HAL_WS_SUBPROTOCOL, reader: credentialFromSubprotocol}).toEqual({
      marker: subprotocol.HAL_WS_SUBPROTOCOL,
      reader: subprotocol.credentialFromSubprotocol,
    });
  });

  it('exports the list_sessions and session_list frame types in the protocol unions', () => {
    const bareRequest: ListSessionsMessage = {type: 'list_sessions'};
    const incoming: IncomingMessage[] = [
      bareRequest,
      {
        type: 'list_sessions',
        limit: 20,
        before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's2'},
      } satisfies ListSessionsMessage,
      {
        type: 'list_sessions',
        before: {updatedAt: 1767225600000, sessionId: 's3'},
      } satisfies ListSessionsMessage,
    ];
    const summary: SessionSummaryFrame = {
      sessionId: 's1',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-01T00:02:00.000Z',
      entryCount: 4,
    };
    const outgoing: OutgoingMessage = {type: 'session_list', sessions: [summary]} satisfies SessionListMessage;

    expect({
      incoming,
      outgoing,
      // @ts-expect-error list_sessions carries no userId: the socket's authenticated user owns the list.
      userId: bareRequest.userId,
    }).toEqual({
      incoming: [
        {type: 'list_sessions'},
        {type: 'list_sessions', limit: 20, before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's2'}},
        {type: 'list_sessions', before: {updatedAt: 1767225600000, sessionId: 's3'}},
      ],
      outgoing: {
        type: 'session_list',
        sessions: [
          {
            sessionId: 's1',
            createdAt: '2026-01-01T00:00:00.000Z',
            updatedAt: '2026-01-01T00:02:00.000Z',
            entryCount: 4,
          },
        ],
      },
      userId: undefined,
    });
  });
});

