      validateMessage({
        type: 'list_sessions',
        limit: 25,
        before: {updatedAt: 1767225600000, sessionId: maxId},
      }),
    ];
    const rejected = [
      validateMessage({type: 'list_sessions', limit: '10'}),
      validateMessage({type: 'list_sessions', limit: 1.5}),
      validateMessage({type: 'list_sessions', limit: -1}),
      validateMessage({type: 'list_sessions', before: null}),
      validateMessage({type: 'list_sessions', before: 'not-an-object'}),
      validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 42}}),
      validateMessage({type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}}),
      validateMessage({
        type: 'list_sessions',
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: `${maxId}a`},
      }),
      validateMessage({type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}}),
      validateMessage({type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}}),
    ];

    expect({
      accepted,
      rejectedValidFlags: rejected.map(entry => entry.valid),
    }).toEqual({
      accepted: [
        {valid: true, data: {type: 'list_sessions'}},
        {
          valid: true,
          data: {
            type: 'list_sessions',
            limit: 0,
            before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
          },
        },
        {
          valid: true,
          data: {
            type: 'list_sessions',
            limit: 25,
            before: {updatedAt: 1767225600000, sessionId: maxId},
          },
        },
      ],
      rejectedValidFlags: Array(rejected.length).fill(false),
    });
  });
});

