export interface PingMessage {
  type: 'ping';
  timestamp: number;
}

export interface ListSessionsMessage {
  type: 'list_sessions';
  limit?: number;
  before?: {
    updatedAt: string | number;
    sessionId: string;
  };
}

export type IncomingMessage = UserMessagePayload | PingMessage | ListSessionsMessage;

import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_SESSION_ID_LENGTH = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

type ParsedField<T> = {ok: true; value: T} | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (!isRecord(payload)) {
    return {valid: false, error: 'Message must be an object'};
  }

  if (typeof payload.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  if (payload.type === 'user_message') return validateUserMessage(payload);
  if (payload.type === 'ping') return validatePingMessage(payload);
  if (payload.type === 'list_sessions') return validateListSessionsMessage(payload);
  return {valid: false, error: `Unknown message type: ${payload.type}`};
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = parseLimit(message.limit);
  if ('valid' in limit) return limit;

  const before = parseBefore(message.before);
  if ('valid' in before) return before;

  const frame: ListSessionsMessage = {type: 'list_sessions'};
  if (limit.value !== undefined) frame.limit = limit.value;
  if (before.value !== undefined) frame.before = before.value;
  return {valid: true, data: frame};
}

function parseLimit(limit: unknown): ParsedField<number | undefined> {
  if (limit === undefined) return {ok: true, value: undefined};
  if (typeof limit !== 'number' || !Number.isInteger(limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }
  if (limit < 0) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }
  return {ok: true, value: limit};
}

function parseBefore(before: unknown): ParsedField<ListSessionsMessage['before']> {
  if (before === undefined) return {ok: true, value: undefined};
  if (!isRecord(before)) {
    return {valid: false, error: 'list_sessions before must be an object'};
  }

  if (typeof before.sessionId !== 'string') {
    return {valid: false, error: 'list_sessions before.sessionId must be a 1-128 character string'};
  }
  if (before.sessionId.length < 1 || before.sessionId.length > MAX_SESSION_ID_LENGTH) {
    return {valid: false, error: 'list_sessions before.sessionId must be a 1-128 character string'};
  }

  const {updatedAt} = before;
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid timestamp'};
  }
  if (!Number.isFinite(new Date(updatedAt).getTime())) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid timestamp'};
  }

  return {ok: true, value: {updatedAt, sessionId: before.sessionId}};
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

